const db = require('better-sqlite3')('/workspace/world.db');
const fs = require('fs');
const path = require('path');

const sender = 'olivia.hr.manager';
const recipient = 'priya.it.lead';
const subject = 'Re: High Priority: Onboarding Equipment Setup Needed - Follow-Up';
const content = \`Hello Priya,

Just a quick follow-up on the onboarding equipment setup for the new contractor. I wanted to confirm that the calendar event for the Onboarding Readiness Sync has been scheduled for September 9, 2026, at 11:00 AM.

Could you please ensure the following items are ready and tracked before the meeting:

1. Standard Windows laptop provisioned
2. VPN access configured
3. Email account set up

Please confirm receipt and let me know if there are any blockers.

Best,
Olivia\`;

// Insert into ob_emails for both sender and recipient inboxes
const insertEmail = db.prepare(
  'INSERT INTO ob_emails (email_id, username, from_address, to_address, subject, content, inbox_owner) VALUES (?, ?, ?, ?, ?, ?, ?)'
);

const senderEmailId = sender + '/' + subject + '.eml';
const recipientEmailId = recipient + '/' + subject + '.eml';

insertEmail.run(senderEmailId, sender, sender + '@company.com', recipient + '@company.com', subject, content, sender);
insertEmail.run(recipientEmailId, recipient, sender + '@company.com', recipient + '@company.com', subject, content, recipient);

console.log('Email inserted into database successfully.');

// Also create .eml files in testbed
const TESTBED_DIR = '/workspace/testbed';
for (const folder of [sender, recipient]) {
  const emailDir = path.join(TESTBED_DIR, 'emails', folder);
  fs.mkdirSync(emailDir, { recursive: true });
  const emlContent = \`From: \${sender}@company.com
To: \${recipient}@company.com
Subject: \${subject}
Content-Type: text/plain; charset=\"utf-8\"
Content-Transfer-Encoding: 7bit
MIME-Version: 1.0

\${content}\`;
  fs.writeFileSync(path.join(emailDir, subject + '.eml'), emlContent);
}

console.log('Email files created in testbed.');

